{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Tocotrienol, a lipophilic isoprenoid with a polar chromanol head, has poor oral bioavailability in humans; this is mechanistically relevant to the query's polar quinone head plus long polyisoprenoid tail and supports a low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lycopene, a large lipophilic isoprenoid, showed only ~2.6% systemic availability in humans; this supports low F for the query's large, poorly water-soluble isoprenoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene, the closest Morgan analogue, had high absolute bioavailability (58.5%) in humans; this is contradictory but less transferable because phytoene lacks the polar quinone head and has different absorption behavior.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hyperforin, a prenylated polar-core natural product, showed high oral bioavailability; this is contradictory but weakly transferable due to lower similarity and smaller size.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a CoQ10-like ubiquinone with a polar quinone head and long polyisoprenoid tail. Human evidence for similar lipophilic isoprenoid lipids (lycopene, tocotrienol) shows low/poor oral bioavailability, while the high phytoene result is less transferable because it lacks the quinone head and has different absorption characteristics.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ10) is present in the evidence set.",
    "Tocotrienol evidence is qualitative ('poor') rather than a numeric F value.",
    "Carotenoid bioavailability is strongly formulation/dose dependent, so numeric values may not transfer directly.",
    "Absolute F for CoQ10 is difficult to measure in humans due to endogenous pools and lack of an IV formulation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

